head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.gEmpNo;
scwin.gAcptNo; // 접수번호
scwin.gFormKorNm; //서식명
scwin.gTitle; // 공시제목

scwin.vScrenID = 'ULDSTF10003.xml';
scwin.gProcsStatCd;
scwin.gTrdHaltMsg;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 부모창의 데이타 셋팅하기
scwin.fn_setParamData = function() {
    /*
		gAcptNo = frame.Provider("../").dts_AcptProcs.NameString(1, 'ACPT_NO');
		gFormKorNm = frame.Provider("../").dts_AcptProcs.NameString(1, 'FORM_KOR_NM');
		gTitle = frame.Provider("../").dts_AcptProcs.NameString(1, 'DISCLS_TITLE');
*/
    //  frame.Provider("/frame_head") 상황에 따라서 바뀌네..?
    scwin.gAcptNo = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'ACPT_NO');
    scwin.gFormKorNm = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'FORM_KOR_NM');
    scwin.gTitle = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'DISCLS_TITLE');
    txb_FormKorNm_Org.setValue(scwin.gFormKorNm);
    txb_Title.setValue(scwin.gTitle);
    scwin.gProcsStatCd = $c.frame.path("../../frame_head").scwin.gProcsStatCd;
    scwin.gTrdHaltMsg = $c.frame.path("../../frame_head").scwin.gTrdHaltMsg;
    scwin.gEmpNo = js_emp_no; // 세션정보 			

};


// 수정하기  
scwin.fn_ModifyDsclTitle = function() {
    if ($c.stf.checkMaxLength(txb_Title, 200, '공시제목') == false) {
        return;
    }
    if (scwin.fn_getProcsSate(scwin.gAcptNo) == false) {
        return false;
    } else {
        var vNewTitle = $c.stf.getObjectValue(txb_Title);
        dts_titleinfo.insertRow();
        dts_titleinfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
        dts_titleinfo.setCellData(1, "DISCLS_TITLE", vNewTitle);
        dts_titleinfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
        dts_titleinfo.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
        var vAnswer = confirm('공시제목을  변경하시겠습니까?');
        if (vAnswer == true) {
            trs_modify.Action = "/DisclosureStudy.do?method=modifyDisclosureTitle&inputMessageId=DSCLTITLE_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&ACPT_NO=" + scwin.gAcptNo;
            trs_modify.KeyName = "toinb_dataid4";
            trs_modify.KeyValue = "JSP(I:pInput=dts_titleinfo)";
            trs_modify.Post();
        }
    }
};





// 처리상태 조회하기
scwin.fn_getProcsSate = function(gAcptNo) {
    var url = "/Viewer.do?method=getDsclProcsStat" + "&inputMessageId=VIEWER_OUT" + "&outputMessageId=VIEWER_OUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_procs_stat.DataID = encodeURI(url);
    dts_procs_stat.reset();
    var vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    var vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    var vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    var vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");
    if (vBLOCK_YN == 'Y') {
        $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    }
    if (scwin.gProcsStatCd != vPROCS_STAT_CD) {
        $c.win.alert("본 공시가 " + vPROCS_DDTM + "에  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        window.open('', '_self', '');
        window.close();
        return false;
    } else {
        return true;
    }
};
scwin.trs_modify_OnSuccess = async function() {
    $c.win.alert("성공적으로 저장되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함
    //frame.Provider("/frame_head").fn_HeadRead() ;
    $c.frame.path("../../frame_head").fn_HeadRead();
};
scwin.trs_modify_OnFail = function() {
    $c.win.alert('trs_modify.OnFail() :' + trs_modify.ErrorMsg);
};
scwin.btn_Cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_ModifyDsclTitle();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(pnl_1);

    // 가우스헤더 셋팅
    dts_titleinfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLTITLE_IN";
    dts_titleinfo.reset();

    // 부모창의 데이타 셋팅하기
    scwin.fn_setParamData();
};
scwin.dts_procs_stat_OnLoadCompleted = function(rowcount) {

};
scwin.dts_procs_stat_OnLoadError = function() {
    $c.win.alert('dts_procs_stat.OnLoadError()' + dts_procs_stat.ErrorMsg);
};
scwin.dts_procs_stat_OnLoadCompleted = function(rowcount) {

};
scwin.dts_procs_stat_OnLoadError = function() {
    $c.win.alert('dts_procs_stat.OnLoadError()' + dts_procs_stat.ErrorMsg);
};
